function element(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node}
function imagePixelSize(image){return image?.naturalWidth>0&&image?.naturalHeight>0?`${image.naturalWidth} x ${image.naturalHeight} pix`:'—'}
function normalizePanelWidths(left,right){const width=$('#app').clientWidth,maxSideTotal=Math.max(PANEL_LEFT_MIN+PANEL_RIGHT_MIN,width-PANEL_CENTER_MIN-PANEL_HANDLES_WIDTH);left=clamp(Number(left)||PANEL_DEFAULTS.left,PANEL_LEFT_MIN,Math.max(PANEL_LEFT_MIN,maxSideTotal-PANEL_RIGHT_MIN));right=clamp(Number(right)||PANEL_DEFAULTS.right,PANEL_RIGHT_MIN,Math.max(PANEL_RIGHT_MIN,maxSideTotal-PANEL_LEFT_MIN));if(left+right>maxSideTotal){const leftExtra=Math.max(0,left-PANEL_LEFT_MIN),rightExtra=Math.max(0,right-PANEL_RIGHT_MIN),extraTotal=leftExtra+rightExtra,availableExtra=Math.max(0,maxSideTotal-PANEL_LEFT_MIN-PANEL_RIGHT_MIN);if(extraTotal>0){left=PANEL_LEFT_MIN+availableExtra*leftExtra/extraTotal;right=PANEL_RIGHT_MIN+availableExtra*rightExtra/extraTotal}else{left=PANEL_LEFT_MIN;right=PANEL_RIGHT_MIN}}return{left:Math.round(left),right:Math.round(right)}}
function applyPanelWidths(left,right,persist=false){const app=$('#app'),widths=normalizePanelWidths(left,right);app.style.setProperty('--left-panel-width',`${widths.left}px`);app.style.setProperty('--right-panel-width',`${widths.right}px`);const leftHandle=$('#leftResizer'),rightHandle=$('#rightResizer'),maxLeft=Math.max(PANEL_LEFT_MIN,app.clientWidth-widths.right-PANEL_CENTER_MIN-PANEL_HANDLES_WIDTH),maxRight=Math.max(PANEL_RIGHT_MIN,app.clientWidth-widths.left-PANEL_CENTER_MIN-PANEL_HANDLES_WIDTH);leftHandle.setAttribute('aria-valuenow',String(widths.left));leftHandle.setAttribute('aria-valuemax',String(Math.round(maxLeft)));rightHandle.setAttribute('aria-valuenow',String(widths.right));rightHandle.setAttribute('aria-valuemax',String(Math.round(maxRight)));if(persist)try{localStorage.setItem(PANEL_LAYOUT_KEY,JSON.stringify(widths))}catch(error){}if(state)schedulePlotDraw();return widths}
function savedPanelWidths(){try{const value=JSON.parse(localStorage.getItem(PANEL_LAYOUT_KEY)||'null');if(value&&Number.isFinite(Number(value.left))&&Number.isFinite(Number(value.right)))return value}catch(error){}return PANEL_DEFAULTS}
function currentPanelWidths(){return{left:$('#reviewPanel').getBoundingClientRect().width||PANEL_DEFAULTS.left,right:$('#detailPanel').getBoundingClientRect().width||PANEL_DEFAULTS.right}}
function beginColumnResize(event){if(event.button!==0||window.innerWidth<=820)return;const handle=event.currentTarget,current=currentPanelWidths();columnDrag={side:handle.dataset.side,pointerId:event.pointerId,startX:event.clientX,left:current.left,right:current.right};handle.classList.add('dragging');document.body.classList.add('resizing-columns');handle.setPointerCapture(event.pointerId);event.preventDefault()}
function moveColumnResize(event){if(!columnDrag||columnDrag.pointerId!==event.pointerId)return;const delta=event.clientX-columnDrag.startX,left=columnDrag.side==='left'?columnDrag.left+delta:columnDrag.left,right=columnDrag.side==='right'?columnDrag.right-delta:columnDrag.right;applyPanelWidths(left,right);event.preventDefault()}
function finishColumnResize(event){if(!columnDrag||columnDrag.pointerId!==event.pointerId)return;const handle=event.currentTarget;columnDrag=null;handle.classList.remove('dragging');document.body.classList.remove('resizing-columns');if(handle.hasPointerCapture?.(event.pointerId))handle.releasePointerCapture(event.pointerId);const current=currentPanelWidths();applyPanelWidths(current.left,current.right,true)}
function handleColumnResizeKey(event){const handle=event.currentTarget,side=handle.dataset.side,current=currentPanelWidths();if(event.key==='Home'){applyPanelWidths(side==='left'?PANEL_DEFAULTS.left:current.left,side==='right'?PANEL_DEFAULTS.right:current.right,true)}else if(event.key==='ArrowLeft'||event.key==='ArrowRight'){const delta=event.key==='ArrowRight'?20:-20;applyPanelWidths(side==='left'?current.left+delta:current.left,side==='right'?current.right-delta:current.right,true)}else return;event.preventDefault()}
function resetColumnWidth(event){const side=event.currentTarget.dataset.side,current=currentPanelWidths();applyPanelWidths(side==='left'?PANEL_DEFAULTS.left:current.left,side==='right'?PANEL_DEFAULTS.right:current.right,true)}
