function initializeColumnResizers(){applyPanelWidths(savedPanelWidths().left,savedPanelWidths().right);document.querySelectorAll('.column-resizer').forEach(handle=>{handle.addEventListener('pointerdown',beginColumnResize);handle.addEventListener('pointermove',moveColumnResize);handle.addEventListener('pointerup',finishColumnResize);handle.addEventListener('pointercancel',finishColumnResize);handle.addEventListener('lostpointercapture',event=>{if(columnDrag?.pointerId===event.pointerId)finishColumnResize(event)});handle.addEventListener('keydown',handleColumnResizeKey);handle.addEventListener('dblclick',resetColumnWidth)})}
function apiError(value,response){const error=value?.error;return new Error(typeof error==='string'?error:error?.message||`HTTP ${response.status}`)}
