async function apiFetch(path,options={}){const response=await fetch(path,{...options,headers:{...apiHeaders(options.saige||{}),...(options.headers||{})}});const value=await response.json().catch(()=>({}));if(!response.ok)throw apiError(value,response);return value}
async function post(path,body={}){const needsLease=runtime.mode==='remote'&&['/api/update','/api/undo','/api/redo','/api/analyze'].includes(path),value=await apiFetch(path,{method:'POST',saige:{json:true,lease:needsLease},body:JSON.stringify(body)});if(Number.isInteger(value.project_revision)&&state)state.project_revision=value.project_revision;return value}
async function fetchSession(){const value=await apiFetch('/api/session');if(value.token){token=value.token;delete value.token}return value}
function notify(message,error=false,persistent=false){const toast=$('#toast');if(toast.dataset.persistent==='true'&&!toast.classList.contains('hidden')&&!persistent)return;toast.textContent=message;toast.style.background=error?'#8b2f29':'#17211cf2';toast.classList.remove('hidden');toast.dataset.persistent=String(persistent);toast.title=persistent?'点击关闭':'';toast.tabIndex=persistent?0:-1;clearTimeout(toastTimer);if(!persistent)toastTimer=setTimeout(()=>toast.classList.add('hidden'),6500)}
async function fetchBootstrap(){const response=await fetch('/api/bootstrap',{cache:'no-store'}),value=await response.json().catch(()=>({}));if(!response.ok)throw apiError(value,response);runtime=value;csrfToken=value.csrf_token||null;document.body.dataset.mode=value.mode||'local';document.body.classList.toggle('remote-mode',value.mode==='remote');if(value.mode==='remote'){$('#remoteIdentity').textContent=`${value.user.email}${value.user.is_admin?' · 管理员':''}`;$('#remoteIdentity').classList.remove('hidden');$('#editLock').classList.remove('hidden');$('#viewRemoteRecycle').classList.toggle('hidden',!value.user.is_admin);$('#openSource').textContent='项目列表';const gpu=value.gpu?.available?`GPU ${value.gpu.name} · ${formatBytes(value.gpu.memory_bytes)}`:'CPU 后备（CUDA 当前不可用）';$('#remoteStorageNotice').textContent=`${gpu} · 单项目 ${formatBytes(value.limits.max_project_size)}`}return value}
function formatBytes(value){const number=Number(value)||0;if(number<1024)return`${number} B`;const units=['KB','MB','GB','TB'];let current=number,index=-1;do{current/=1024;index++}while(current>=1024&&index<units.length-1);return`${current>=10||index>1?current.toFixed(1):current.toFixed(2)} ${units[index]}`}
function formatTime(value){if(!value)return'—';return new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeStyle:'short'}).format(new Date(Number(value)*1000))}
function setRemoteProjectError(message=''){const box=$('#remoteProjectError');box.textContent=message;box.classList.toggle('hidden',!message)}
async function loadRemoteProjects(recycled=false){setRemoteProjectError();const list=$('#remoteProjectList');list.replaceChildren(element('p','dialog-note',recycled?'正在加载回收区…':'正在加载共享项目…'));try{const value=await apiFetch(recycled?'/api/admin/recycle':'/api/projects'),projects=value.projects||[];list.replaceChildren();$('#remoteProjectsTitle').textContent=recycled?'项目回收区':'远程共享项目';$('#viewRemoteRecycle').textContent=recycled?'返回共享项目':'回收区';$('#viewRemoteRecycle').dataset.recycled=String(recycled);if(!projects.length){list.append(element('div','remote-project-empty',recycled?'回收区为空。':'还没有共享项目。点击“上传新项目”创建第一个项目。'));return}for(const project of projects){const card=element('article','remote-project-entry'),head=element('div','remote-project-entry-head'),title=element('div'),buttons=element('div','remote-project-entry-actions');title.append(element('strong','',project.name),element('span','',`${project.format} · ${formatBytes(project.storage_bytes)} · revision ${project.revision}`));head.append(title,buttons);if(recycled){const restore=element('button','primary','恢复项目');restore.type='button';restore.addEventListener('click',()=>restoreRemoteProject(project));buttons.append(restore)}else{const open=element('button','primary','打开工作台');open.type='button';open.addEventListener('click',()=>openRemoteProject(project.id));buttons.append(open);if(project.permissions?.delete){const remove=element('button','danger ghost','移入回收区');remove.type='button';remove.addEventListener('click',()=>recycleRemoteProject(project));buttons.append(remove)}}const lock=project.lock?`编辑：${project.lock.holder}（至 ${formatTime(project.lock.expires_at)}）`:'当前无人编辑',analysis=project.analysis?.state?`分析：${project.analysis.state}${project.analysis.state==='queued'?`（队列）`:''}`:'尚未分析';card.append(head,element('p','remote-project-meta',recycled?`已进入回收区 · 24 小时后永久清理`:`${lock} · ${analysis} · 到期 ${formatTime(project.expires_at)}`));list.append(card)}}catch(error){list.replaceChildren();setRemoteProjectError(error.message)}}
function showRemoteProjects(){if(runtime.mode!=='remote')return openSourceDialog();loadRemoteProjects();if(!$('#remoteProjectsDialog').open)$('#remoteProjectsDialog').showModal()}
function remoteFilterQuery(limit,offset=0){return new URLSearchParams({limit:String(limit),offset:String(offset),search:$('#search').value.trim(),status:$('#statusFilter').value,label:$('#classFilter').value,min_score:$('#minScore').value}).toString()}
async function refreshRemoteItems({preserveSelection=true,offset=remoteQueueOffset}={}){if(runtime.mode!=='remote'||!remoteProjectId||!state)return;offset=Math.max(0,Number(offset)||0);const generation=++remoteFilterGeneration,[page,sample]=await Promise.all([apiFetch(`/api/projects/${remoteProjectId}/items?${remoteFilterQuery(REMOTE_PAGE_LIMIT,offset)}`),apiFetch(`/api/projects/${remoteProjectId}/feature-sample?${remoteFilterQuery(PLOT_LIMIT)}`)]);if(generation!==remoteFilterGeneration)return;remoteQueueTotal=Number(page.total)||0;if(remoteQueueTotal&&offset>=remoteQueueTotal)return refreshRemoteItems({preserveSelection,offset:Math.max(0,Math.floor((remoteQueueTotal-1)/REMOTE_PAGE_LIMIT)*REMOTE_PAGE_LIMIT)});remoteQueueOffset=offset;remoteQueueItems=page.items||[];const union=new Map((sample.items||[]).map(item=>[item.id,item]));for(const item of remoteQueueItems)union.set(item.id,item);state.items=[...union.values()];rebuildItemIndex();remoteQueueItems=page.items||[];filteredRankById=new Map(remoteQueueItems.map((item,index)=>[item.id,index]));if(!preserveSelection||!itemById.has(current))current=remoteQueueItems[0]?.id||state.items[0]?.id||null}
async function changeRemotePage(offset){try{await refreshRemoteItems({preserveSelection:false,offset});render();$('#list').scrollTop=0;$('#list').querySelector('.item')?.focus({preventScroll:true})}catch(error){notify(`加载复查队列失败：${error.message}`,true)}}
async function openRemoteProject(projectId){remoteProjectId=projectId;sessionStorage.setItem('saige-remote-project-id',projectId);remoteLeaseToken=sessionStorage.getItem(`saige-remote-lease-${projectId}`)||null;try{installState(await fetchSession());renderFilters();await refreshRemoteItems({preserveSelection:false});render();if($('#remoteProjectsDialog').open)$('#remoteProjectsDialog').close();if(!state.read_only&&remoteLeaseToken)startLeaseHeartbeat();if(state.read_only)notify(state.lock?`项目由 ${state.lock.holder} 编辑；当前为只读。`:'项目默认只读；点击“开始编辑”取得编辑锁。');if(['queued','running'].includes(state.job?.state))startPolling()}catch(error){setRemoteProjectError(error.message)}}
function stopLeaseHeartbeat(){clearInterval(remoteLeaseTimer);remoteLeaseTimer=null}
function startLeaseHeartbeat(){stopLeaseHeartbeat();if(runtime.mode!=='remote'||!remoteProjectId||!remoteLeaseToken)return;remoteLeaseTimer=setInterval(async()=>{try{await apiFetch(`/api/projects/${remoteProjectId}/lock/heartbeat`,{method:'POST',saige:{json:true},headers:{'X-Edit-Lease':remoteLeaseToken},body:'{}'})}catch(error){stopLeaseHeartbeat();remoteLeaseToken=null;sessionStorage.removeItem(`saige-remote-lease-${remoteProjectId}`);if(state){state.read_only=true;state.lock=null;render();notify(`编辑锁已失效：${error.message}`,true,true)}}},30000)}
async function toggleRemoteEdit(){if(!remoteProjectId)return showRemoteProjects();try{if(remoteLeaseToken&&!state?.read_only){await apiFetch(`/api/projects/${remoteProjectId}/lock`,{method:'DELETE',headers:{'X-Edit-Lease':remoteLeaseToken}});remoteLeaseToken=null;sessionStorage.removeItem(`saige-remote-lease-${remoteProjectId}`);stopLeaseHeartbeat()}else{let value;try{value=await apiFetch(`/api/projects/${remoteProjectId}/lock`,{method:'POST',saige:{json:true},body:'{}'})}catch(error){if(!runtime.user?.is_admin||!state?.lock||!confirm(`${state.lock.holder} 的编辑租约尚未到期。确认以管理员身份强制接管？`))throw error;value=await apiFetch(`/api/projects/${remoteProjectId}/lock`,{method:'POST',saige:{json:true},body:JSON.stringify({force:true})})}remoteLeaseToken=value.lock.token;sessionStorage.setItem(`saige-remote-lease-${remoteProjectId}`,remoteLeaseToken);startLeaseHeartbeat()}installState(await fetchSession());renderFilters();await refreshRemoteItems();render();notify(state.read_only?'已释放编辑锁，项目回到只读状态。':'已取得编辑锁；其他成员仍可只读查看。')}catch(error){notify(error.message,true)}}
async function recycleRemoteProject(project){if(!confirm(`将“${project.name}”移入回收区？24 小时内管理员可恢复。`))return;try{await apiFetch(`/api/admin/projects/${project.id}`,{method:'DELETE'});if(project.id===remoteProjectId){remoteProjectId=null;remoteLeaseToken=null;state=null;sessionStorage.removeItem('saige-remote-project-id')}await loadRemoteProjects()}catch(error){setRemoteProjectError(error.message)}}
async function restoreRemoteProject(project){try{await apiFetch(`/api/admin/projects/${project.id}/restore`,{method:'POST',saige:{json:true},body:'{}'});notify(`项目“${project.name}”已从回收区恢复。`);await loadRemoteProjects(true)}catch(error){setRemoteProjectError(error.message)}}
function updateRemoteUploadFields(){const format=$('#remoteProjectFormat').value,folder=format==='folder',external=format==='srproj'||format==='saige-json';$('#remotePrimaryField').classList.toggle('hidden',folder);$('#remoteDatasetField').classList.toggle('hidden',!folder);$('#remoteImageRootField').classList.toggle('hidden',!external);$('#remotePrimaryFile').accept=format==='visionproj'?'.visionproj':format==='srproj'?'.srproj':'.json'}
function openRemoteUpload(){setRemoteProjectError();if($('#remoteProjectsDialog').open)$('#remoteProjectsDialog').close();$('#remoteUploadForm').reset();$('#remoteProjectFormat').value='visionproj';updateRemoteUploadFields();$('#remoteUploadError').classList.add('hidden');$('#remoteUploadProgress').classList.add('hidden');$('#remoteUploadDialog').showModal();$('#remoteProjectName').focus()}
function logicalDirectoryPath(file,prefix){const raw=(file.webkitRelativePath||file.name).replace(/\\/g,'/'),parts=raw.split('/').filter(Boolean);if(parts.length>1)parts.shift();return`${prefix}/${parts.join('/')}`}
function remoteUploadSelection(){const format=$('#remoteProjectFormat').value,name=$('#remoteProjectName').value.trim();if(!name)throw new Error('请输入项目名称。');const entries=[];let primaryPath;if(format==='folder'){for(const file of $('#remoteDatasetRoot').files)entries.push({file,logical_path:logicalDirectoryPath(file,'dataset'),role:'data'});if(!entries.length)throw new Error('请选择按类别分组的数据集文件夹。');primaryPath='dataset'}else{const primary=$('#remotePrimaryFile').files[0];if(!primary)throw new Error('请选择项目文件。');primaryPath=`project/${primary.name}`;entries.push({file:primary,logical_path:primaryPath,role:'primary'});if(format==='srproj'||format==='saige-json')for(const file of $('#remoteImageRoot').files)entries.push({file,logical_path:logicalDirectoryPath(file,'roots'),role:'data'})}return{name,format,primaryPath,entries}}
function remoteUploadResumeKey(selection){const signature=selection.entries.map(entry=>`${entry.logical_path}:${entry.file.size}:${entry.file.lastModified}`).sort().join('|');return`saige-upload-v1:${selection.format}:${selection.primaryPath}:${stablePlotHash(signature)}`}
async function createOrResumeUpload(selection,total,resumeKey,signal){let saved;try{saved=JSON.parse(localStorage.getItem(resumeKey)||'null')}catch(error){}if(saved?.id){try{const value=await apiFetch(`/api/uploads/${saved.id}`,{signal});if(value.upload.total_size===total&&value.upload.file_count===selection.entries.length&&['registering','uploading','needs-files'].includes(value.upload.state)){notify('已找到未完成上传，将幂等续传已校验分块。');return value.upload}}catch(error){localStorage.removeItem(resumeKey)}}const upload=await apiFetch('/api/uploads',{method:'POST',saige:{json:true},signal,body:JSON.stringify({name:selection.name,format:selection.format,total_size:total,file_count:selection.entries.length,primary_path:selection.primaryPath})});localStorage.setItem(resumeKey,JSON.stringify({id:upload.id,created_at:Date.now()}));return upload}
async function sha256Buffer(buffer){const digest=await crypto.subtle.digest('SHA-256',buffer);return[...new Uint8Array(digest)].map(value=>value.toString(16).padStart(2,'0')).join('')}
function setUploadBusy(busy){for(const control of $('#remoteUploadForm').querySelectorAll('button,input,select'))control.disabled=busy;$('#cancelRemoteUpload').disabled=false;$('#cancelRemoteUpload').textContent=busy?'中止上传':'取消'}
function showUploadProgress(message,received,total){const box=$('#remoteUploadProgress'),percent=total?Math.min(100,Math.round(received/total*100)):0;box.classList.remove('hidden');$('#remoteUploadMessage').textContent=message;$('#remoteUploadPercent').textContent=`${percent}%`;$('#remoteUploadBar').value=percent}
async function uploadRemoteProject(event){event.preventDefault();const errorBox=$('#remoteUploadError');errorBox.classList.add('hidden');let selection,resumeKey;try{selection=remoteUploadSelection();const total=selection.entries.reduce((sum,entry)=>sum+entry.file.size,0);if(total>runtime.limits.max_project_size)throw new Error(`项目超过 ${formatBytes(runtime.limits.max_project_size)} 上限。`);remoteUploadController=new AbortController();setUploadBusy(true);showUploadProgress('创建或恢复可续传上传…',0,total);resumeKey=remoteUploadResumeKey(selection);const upload=await createOrResumeUpload(selection,total,resumeKey,remoteUploadController.signal);let hashed=0;for(const entry of selection.entries){entry.sha256=await SaigeUploadSha256.hashFile(entry.file,{signal:remoteUploadController.signal,onProgress:processed=>showUploadProgress(`计算完整校验：${entry.logical_path}`,hashed+processed,total)});hashed+=entry.file.size}const mapped=new Map();for(let start=0;start<selection.entries.length;start+=500){const batch=selection.entries.slice(start,start+500),value=await apiFetch(`/api/uploads/${upload.id}/files`,{method:'POST',saige:{json:true},signal:remoteUploadController.signal,body:JSON.stringify({files:batch.map(entry=>({logical_path:entry.logical_path,role:entry.role,size:entry.file.size,chunk_count:Math.max(1,Math.ceil(entry.file.size/upload.chunk_size)),sha256:entry.sha256}))})});for(const file of value.files)mapped.set(file.logical_path,file.file_id)}let sent=0;for(const entry of selection.entries){const fileId=mapped.get(entry.logical_path),chunks=Math.max(1,Math.ceil(entry.file.size/upload.chunk_size));for(let index=0;index<chunks;index++){const payload=await entry.file.slice(index*upload.chunk_size,Math.min(entry.file.size,(index+1)*upload.chunk_size)).arrayBuffer(),hash=await sha256Buffer(payload);showUploadProgress(`上传 ${entry.logical_path}`,sent,total);await apiFetch(`/api/uploads/${upload.id}/files/${fileId}/chunks/${index}`,{method:'PUT',saige:{},signal:remoteUploadController.signal,headers:{'Content-Type':'application/octet-stream','X-Chunk-SHA256':hash},body:payload});sent+=payload.byteLength;showUploadProgress(`已校验 ${entry.logical_path}`,sent,total)}}showUploadProgress('服务端正在校验并导入项目…',sent,total);const completed=await apiFetch(`/api/uploads/${upload.id}/complete`,{method:'POST',saige:{json:true},signal:remoteUploadController.signal,body:'{}'});if(completed.unresolved?.length)throw new Error(`仍有 ${completed.unresolved.length} 个图像引用未映射。请重新上传并选择正确的图像根目录。`);localStorage.removeItem(resumeKey);$('#remoteUploadDialog').close();notify(`项目“${completed.project.name}”上传并严格校验完成。`);await openRemoteProject(completed.project.id)}catch(error){if(error.name!=='AbortError'){errorBox.textContent=error.message;errorBox.classList.remove('hidden')}else notify('上传已中止；再次选择同一项目可幂等续传已校验分块。')}finally{remoteUploadController=null;setUploadBusy(false)}}
