async function pickSourcePath(kind,targetId,append,button,purpose='source'){if(sourceDialogBusy)return;clearSourceError();const original=button.textContent;let failed=false;setSourceControlsDisabled(true);button.textContent='等待资源管理器…';try{const value=await post('/api/pick-path',{kind,purpose});if(value.cancelled||!value.path)return;const input=$('#'+targetId);if(append){const roots=input.value.split(';').map(root=>root.trim()).filter(Boolean);if(!roots.some(root=>root.toLocaleLowerCase()===value.path.toLocaleLowerCase()))roots.push(value.path);input.value=roots.join('; ');$('#previewRootDetails').open=true}else input.value=value.path}catch(error){failed=true;setSourceError(error.message,$('#'+targetId))}finally{button.textContent=original;setSourceControlsDisabled(false);if($('#sourceDialog').open)(failed?$('#'+targetId):button).focus({preventScroll:true})}}
async function confirmOpen(event){event.preventDefault();if(sourceDialogBusy)return;clearSourceError();const input=$('#sourceInput'),path=input.value.trim();if(!path){setSourceError('请选择项目文件或数据集文件夹。',input);input.focus();return}let allowed_preview_roots;try{allowed_preview_roots=parsePreviewRoots()}catch(error){const field=$('#previewRoots');setSourceError(error.message,field);field.focus();return}const button=$('#confirmOpen');let failed=false,failedField=input;setSourceControlsDisabled(true);button.textContent='正在读取…';try{installState(await post('/api/open',{source:path,allowed_preview_roots}));renderFilters();current=filtered()[0]?.id||null;$('#sourceDialog').close();notify(`已打开 ${state.name}，共 ${state.items.length} 个复查项。`);render()}catch(error){failed=true;failedField=sourceErrorField(error.message);setSourceError(error.message,failedField)}finally{button.textContent='打开';setSourceControlsDisabled(false);if(failed&&$('#sourceDialog').open)failedField.focus()}}
function refreshAnalysisAvailability(){const deps=state.dependencies||{},model=state.model_status||{},access=$('#modelAccess').value||'local_only',modelReady=model.cached===true||access==='download_if_missing',modelMessage=!model.cached&&access==='download_if_missing'?'模型尚未缓存；本次已明确允许下载':model.message,box=$('#dependencyState');box.textContent=[deps.message,modelMessage].filter(Boolean).join(' · ');box.classList.toggle('missing',!deps.ready||!modelReady);$('#confirmAnalysis').disabled=!deps.ready||!modelReady||!state.source}
function openAnalysisDialog(){const config=state.analysis_config||{};$('#backgroundMode').value=config.background_mode||'original';$('#inputSize').value=String(config.input_size||'auto');$('#projection').value=config.projection||'umap';$('#device').value=runtime.mode==='remote'?'auto':config.device||'auto';$('#modelAccess').value=runtime.mode==='remote'?'local_only':config.model_access||'local_only';$('#device').disabled=runtime.mode==='remote';$('#modelAccess').disabled=runtime.mode==='remote';$('#roiExpansion').value=Math.round((config.roi_expansion??.15)*100);$('#roiValue').textContent=`${$('#roiExpansion').value}%`;$('#maskPooling').checked=config.mask_pooling!==false;refreshAnalysisAvailability();$('#analysisDialog').showModal()}
async function startAnalysis(event){event.preventDefault();const config={background_mode:$('#backgroundMode').value,input_size:$('#inputSize').value,projection:$('#projection').value,device:$('#device').value,model_access:$('#modelAccess').value,roi_expansion:Number($('#roiExpansion').value)/100,mask_pooling:$('#maskPooling').checked};try{const value=await post('/api/analyze',config);state.job=value.job;$('#analysisDialog').close();render();startPolling()}catch(error){notify(error.message,true)}}
async function pollJob(){try{const value=await apiFetch('/api/job');state.job=value.job;renderHeader();renderJob();$('#undo').disabled=true;$('#redo').disabled=true;if(['queued','running'].includes(value.job.state)){pollFailures=0;pollTimer=setTimeout(pollJob,value.job.state==='queued'?1500:650);return}const finished=value.job;installState(await fetchSession());renderFilters();if(runtime.mode==='remote')await refreshRemoteItems();pollFailures=0;render();if(finished.state==='completed'){const device=finished.result?.execution?.device,deviceLabel=device==='cuda'?'GPU':device==='cpu'?'CPU':'未知设备',dtype=finished.result?.execution?.dtype?` · ${finished.result.execution.dtype}`:'',fallback=finished.result?.device_fallback?'；GPU 不可用，已自动改用 CPU':'';notify(`分析完成，使用 ${deviceLabel}${dtype}${fallback}，输入尺寸 ${finished.result?.effective_input_size??'未知'}px。`)}else if(finished.state==='failed')notify(finished.error||'分析失败',true)}catch(error){pollFailures++;if(state?.job){state.job={...state.job,state:'running',message:`连接暂时中断，正在自动重试（${pollFailures}）`};renderJob();$('#undo').disabled=true;$('#redo').disabled=true;if(pollFailures===1)notify(`分析状态连接中断：${error.message}。工作台会自动重试。`,true);pollTimer=setTimeout(pollJob,Math.min(8000,650*2**Math.min(pollFailures,4)));return}notify(error.message,true)}}
async function cancelRemoteAnalysis(){if(runtime.mode!=='remote'||!state?.job?.id)return;try{const value=await apiFetch(`/api/projects/${remoteProjectId}/analysis-runs/${state.job.id}`,{method:'DELETE',saige:{lease:true}});state.job=value.job;render();notify('分析任务已取消；工作进程将安全释放模型与显存。')}catch(error){notify(error.message,true)}}
