function startPolling(){clearTimeout(pollTimer);pollFailures=0;pollTimer=setTimeout(pollJob,0)}
function openExportDialog(){const changed=state.changed_count||0,total=runtime.mode==='remote'?(state.item_count||state.items.length):state.items.length;$('#exportSummary').textContent=`${state.name}：${total} 个复查项，${changed} 个类别修改。${runtime.mode==='remote'?'服务器会生成并复读校验独立下载文件，只读原件永不覆盖。':'默认导出到新的修正版，原项目保持不变。'}`;$('#exportCorrected').disabled=runtime.mode==='remote'?!remoteProjectId:(!changed||!state.source);$('#overwriteSource').disabled=!changed||!state.source;$('#overwriteConfirmation').value='';$('#exportDialog').showModal()}
async function doExport(path,body={}){try{const value=await post(path,body),result=value.export_result;if(runtime.mode==='remote'){if(result.download_url){const link=document.createElement('a');link.href=result.download_url;link.download=result.filename||'';document.body.append(link);link.click();link.remove()}$('#exportDialog').close();notify(`导出已严格复读校验${result.filename?`：${result.filename}`:''}，下载已经开始。`,false,true);return}let refreshError=null;if(value.reload_required)state.requires_source_reload=true;if(value.reload_required&&!value.reload_error){try{installState(await fetchSession());renderFilters();current=filtered()[0]?.id||null}catch(error){refreshError=error;state.requires_source_reload=true}}$('#exportDialog').close();const reloadWarning=value.reload_error?`\n源已覆盖，但自动重载失败：${value.reload_error}\n请重新打开数据源后再继续。`:refreshError?`\n源已覆盖且服务端已重载，但工作台刷新失败：${refreshError.message}\n请刷新页面或重新打开数据源后再继续。`:'',persistent=Boolean(result.recovery_copy||value.reload_error||refreshError),closeHint=persistent?'\n点击此提示关闭。':'';notify(`操作完成\n输出：${result.output}${result.backup?`\n备份：${result.backup}`:''}${result.recovery_copy?`\n恢复副本：${result.recovery_copy}`:''}${reloadWarning}${closeHint}`,Boolean(value.reload_error||refreshError),persistent);render()}catch(error){notify(error.message,true)}}
async function undo(){try{applyMutation(await post('/api/undo'));if(runtime.mode==='remote')await refreshRemoteItems();render()}catch(error){notify(error.message,true)}}async function redo(){try{applyMutation(await post('/api/redo'));if(runtime.mode==='remote')await refreshRemoteItems();render()}catch(error){notify(error.message,true)}}
function beginPlotDrag(event){if(event.button!==0||plotGesture.pointerId!==null)return;const point=plotEventPoint(event);plotGesture.pointerId=event.pointerId;plotGesture.startX=point.x;plotGesture.startY=point.y;plotGesture.panX=plotView.panX;plotGesture.panY=plotView.panY;plotGesture.moved=false;lastPlotPointer=point;event.currentTarget.focus({preventScroll:true});event.currentTarget.setPointerCapture(event.pointerId)}
function movePlotPointer(event){const point=plotEventPoint(event);lastPlotPointer=point;if(plotGesture.pointerId===event.pointerId){const dx=point.x-plotGesture.startX,dy=point.y-plotGesture.startY;if(!plotGesture.moved&&Math.hypot(dx,dy)>=PLOT_DRAG_THRESHOLD){plotGesture.moved=true;event.currentTarget.classList.add('dragging');clearPlotHover()}if(plotGesture.moved){plotView.panX=plotGesture.panX+dx;plotView.panY=plotGesture.panY+dy;schedulePlotDraw();event.preventDefault()}return}updatePlotHoverAt(point.x,point.y)}
function finishPlotDrag(event,cancelled=false){if(plotGesture.pointerId!==event.pointerId)return;const canvas=event.currentTarget,moved=plotGesture.moved;plotGesture.pointerId=null;plotGesture.moved=false;canvas.classList.remove('dragging');if(canvas.hasPointerCapture?.(event.pointerId))canvas.releasePointerCapture(event.pointerId);if(moved)suppressPlotClickUntil=Date.now()+300;if(!cancelled&&lastPlotPointer)updatePlotHoverAt(lastPlotPointer.x,lastPlotPointer.y)}
function handlePlotWheel(event){event.preventDefault();const point=plotEventPoint(event),delta=normalizedWheelDelta(event.deltaY,event.deltaMode,point.height),factor=clamp(Math.exp(-delta*.0015),.5,2);lastPlotPointer=point;zoomPlotBy(factor,point)}
function handlePlotKeydown(event){let handled=true;if(event.key==='+'||event.key==='=')zoomPlotBy(1.25);else if(event.key==='-'||event.key==='_')zoomPlotBy(.8);else if(event.key==='0'||event.key.toLowerCase()==='f')fitCurrentPlot();else if(event.key==='ArrowLeft')plotView.panX+=36;else if(event.key==='ArrowRight')plotView.panX-=36;else if(event.key==='ArrowUp')plotView.panY+=36;else if(event.key==='ArrowDown')plotView.panY-=36;else handled=false;if(handled){event.preventDefault();event.stopPropagation();if(event.key.startsWith('Arrow'))schedulePlotDraw()}}
